mapper.select:
SELECT count(1) FROM system_docking.api_platform_index_info a LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id=b.id LEFT JOIN system_docking.api_interface_system_info c ON b.system_id=c.id WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1'
AND a.is_keyPoint=#{params.is_keyPoint}
AND a.index_name LIKE '%${params.indicatorkeyWord}%'
AND a.platform_id=#{params.platformId}

SELECT a.ID,a.platform_id,b.platfrom_name,a.index_code,a.index_name,a.index_desc,a.is_monitor
FROM system_docking.api_platform_index_info a
LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id=b.id
LEFT JOIN system_docking.api_interface_system_info c ON b.system_id=c.id
WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1'

    AND a.is_keyPoint=#{params.is_keyPoint}


    AND a.index_name LIKE '%${params.indicatorkeyWord}%'


    AND a.platform_id=#{params.platformId}

LIMIT ${params.rows} OFFSET ${params.page}

mapper.update:
UPDATE
system_docking.api_platform_index_info
SET
MODIFIER=#{params.userName},
MODIFY_DATE=#{params.modifyDate}

    ,is_keyPoint=#{params.is_keyPoint}


    ,index_desc=#{params.index_desc}


    ,is_monitor=#{params.is_monitor}

WHERE ID IN

    #{indexId}
